func uploadAssetWithRetry(ctx *context.Context, upload *config.Upload, target, username, secret string, headers map[string]string, a *asset, check ResponseChecker, attempt, maxAttempts int, cfg *config.RetryConfig, kind string, publishAttempts *[]PublishAttemptsEntry) (*h.Response, error) {
	entry := PublishAttemptsEntry{
		Publisher: kind,
		Instance:  upload.Name,
		Target:    target,
		Attempt:   attempt,
	}

	req, err := newUploadRequest(ctx, upload.Method, target, username, secret, headers, a)

	// Record publish attempts on the artifact
	SortPublishAttempts(publishAttempts)
	artifact.Extra[ExtraPublishAttempts] = publishAttempts
	return nil
}

