import Browser from '../../src/browser/Browser';
import BrowserContext from '../../src/browser/BrowserContext';
import BrowserPage from '../../src/browser/BrowserPage';
import DefaultBrowserSettings from '../../src/browser/DefaultBrowserSettings';
import { describe, it, expect, afterEach, vi } from 'vitest';

describe('Browser', () => {
	afterEach(() => {
		vi.restoreAllMocks();
	});

	describe('get contexts()', () => {
		it('Returns the contexts.', async () => {
			const browser = new Browser();
			expect(browser.contexts.length).toBe(1);
			expect(browser.contexts[0]).toBe(browser.defaultContext);

			const incognitoContext = browser.newIncognitoContext();
			expect(browser.contexts.length).toBe(2);
			expect(browser.contexts[0]).toBe(browser.defaultContext);
			expect(browser.contexts[1]).toBe(incognitoContext);

			await incognitoContext.close();

			expect(browser.contexts.length).toBe(1);
			expect(browser.contexts[0]).toBe(browser.defaultContext);

			let error: Error | null = null;

			try {
				await browser.defaultContext.close();
			} catch (e) {
				error = <Error>e;
			}

			expect(error).toEqual(
				new Error(
					'Cannot close the default context. Use `browser.close()` to close the browser instead.'
				)
			);
			expect(browser.contexts.length).toBe(1);

			await browser.close();

			expect(browser.contexts.length).toBe(0);
		});
	});

	describe('get closed()', () => {
		it('Returns "false" if the browser is not closed.', () => {
			expect(new Browser().closed).toBe(false);
		});

		it('Returns "true" if the browser is closed.', async () => {
			const browser = new Browser();
			await browser.close();
			expect(browser.closed).toBe(true);
		});
	});

import type IBrowserFrame from '../types/IBrowserFrame.js';
import type IBrowserPage from '../types/IBrowserPage.js';
import BrowserFrameFactory from './BrowserFrameFactory.js';

/**
 * Browser page utility.
 */
export default class BrowserPageUtility {
	/**
	 * Returns frames for a page.
	 *
	 * @param page Page.
	 * @returns Frames.
	 */
	public static getFrames(page: IBrowserPage): IBrowserFrame[] {
		return this.findFrames(page.mainFrame);
	}

	/**
	 * Aborts all ongoing operations and destroys the page.
	 *
	 * @param page Page.
	 */
	public static closePage(page: IBrowserPage): Promise<void> {
		if (page.closed) {
			return Promise.resolve();
		}

		(<boolean>page.closed) = true;

		const index = page.context.pages.indexOf(page);

		if (index !== -1) {
			page.context.pages.splice(index, 1);
		}

		page.virtualConsolePrinter.close();

		// Using Promise instead of async/await to prevent microtask
		return BrowserFrameFactory.destroyFrame(page.mainFrame);
	}

	/**
	 * Returns all frames.
	 *
	 * @param parentFrame Parent frame.
	 * @returns Frames, including the parent.
	 */
	private static findFrames(parentFrame: IBrowserFrame): IBrowserFrame[] {
		let frames = [parentFrame];
		for (const frame of parentFrame.childFrames) {
			frames = frames.concat(this.findFrames(frame));
		}
		return frames;
	}
}

