// MuxSide indicates which side of the mux session this is.
type MuxSide int

const (
	MuxSideClient MuxSide = iota
	MuxSideServer
)

const (
	MuxPriorityHigh   uint8 = 0
	MuxPriorityNormal uint8 = 1
	MuxPriorityLow    uint8 = 2
)

// Frame types for the mux wire protocol.
const (
	muxTypeData         uint8 = 1
	muxTypeOpenStream   uint8 = 2
	muxTypeCloseStream  uint8 = 3
	muxTypeWindowUpdate uint8 = 4
)

// Frame header size in bytes:
//
//	streamID: 4 bytes
//	frameType: 1 byte
//	length: 2 bytes
//	priority: 1 byte
//	windowSize: 4 bytes
//	= 12 bytes total
const muxFrameHeaderSize = 12

// MuxConfig configures a MuxSession.
type MuxConfig struct {
	Side         MuxSide
	MaxFrameSize int // maximum payload bytes per data frame
	SendWindow   int // per-stream send window in bytes
	RecvWindow   int // per-stream receive window in bytes
}

// DefaultMuxConfig returns a MuxConfig with sensible defaults.
func DefaultMuxConfig() MuxConfig {
	return MuxConfig{
		Side:         MuxSideClient,
		MaxFrameSize: 4096,
		SendWindow:   65536,
		RecvWindow:   65536,
	}
}

// muxFrame is the wire format for mux protocol frames.
type muxFrame struct {
	streamID   uint32
	frameType  uint8
	length     uint16
	priority   uint8
	windowSize uint32
	payload    []byte
}

// marshalFrame encodes a muxFrame into a byte slice.
func marshalFrame(f muxFrame) []byte {
	size := muxFrameHeaderSize + int(f.length)
	hdr := make([]byte, size)
	binary.BigEndian.PutUint32(hdr[0:4], f.streamID)
	hdr[4] = f.frameType
	binary.BigEndian.PutUint16(hdr[5:7], f.length)
	hdr[7] = f.priority
	binary.BigEndian.PutUint32(hdr[8:12], f.windowSize)
	copy(hdr[muxFrameHeaderSize:], f.payload)
	return hdr
}

// unmarshalFrame decodes a byte slice into a muxFrame. It returns the frame
// and whether the buffer was large enough.
func unmarshalFrame(buf []byte) (muxFrame, bool) {
	if len(buf) < muxFrameHeaderSize {
		return muxFrame{}, false
	}
	f := muxFrame{
		streamID:   binary.BigEndian.Uint32(buf[0:4]),
		frameType:  buf[4],
		length:     binary.BigEndian.Uint16(buf[5:7]),
		priority:   buf[7],
		windowSize: binary.BigEndian.Uint32(buf[8:12]),
	}
	need := muxFrameHeaderSize + int(f.length)
	if need > len(buf) {
		return muxFrame{}, false
	}
	if f.length > 0 {
		f.payload = buf[muxFrameHeaderSize:need]
	}
	return f, true
}

// MuxStream implements a bidirectional ordered byte stream within a MuxSession.
type MuxStream struct {
	id      uint32
	session *MuxSession

	// inbound buffering — accessed only under session.mu
	recvBuf    []byte
	recvClosed bool // remote has sent closeStream (no more data will arrive)

	// readSignal is used to wake up a blocked Read when data arrives or the
	// stream is closed.
	readSignal chan struct{}

	// outbound flow control — accessed only under session.mu
