import type { Schema, StoreType } from './types';

/**
 * Get default values from a schema.
 * Returns null for tags (empty schemas) or if no defaults exist.
 */
/* @inline @pure */ export function getSchemaDefaults(
    schema: Record<string, any> | (() => unknown),
    type: StoreType
): Record<string, any> | null {
    if (type === 'aos') {
        return typeof schema === 'function' ? (schema() as Record<string, any>) : null;
    }

    if (!schema || typeof schema === 'function' || Object.keys(schema).length === 0) return null;

    const defaults: Record<string, any> = {};
    for (const key in schema) {
        if (typeof schema[key] === 'function') {
            defaults[key] = schema[key]();
        } else {
            defaults[key] = schema[key];
        }
    }
    return defaults;
}

export /* @inline @pure */ function validateSchema(schema: Schema) {
    for (const key in schema) {
        const value = schema[key as keyof Schema];
        if (value !== null && typeof value === 'object') {
            const kind = Array.isArray(value) ? 'array' : 'object';
            throw new Error(`Koota: ${key} is an ${kind}, which is not supported in traits.`);
        }
    }
}

import { beforeEach, describe, expect, expectTypeOf, it } from 'vitest';
import { $internal, createWorld, type Entity, getStore, trait, unpackEntity } from '../src';

const Foo = trait();
const Bar = trait({ value: 0 });
const Baz = trait(() => ({ value: 0 }));

describe('Entity', () => {
    const world = createWorld();

    beforeEach(() => {
        world.reset();
    });

    it('should create and destroy an entity', () => {
        const entityA = world.spawn();
        expect(entityA).toBe(1);

        const entityB = world.spawn();
        expect(entityB).toBe(2);

        const entityC = world.spawn();
        expect(entityC).toBe(3);

        entityA.destroy();
        entityC.destroy();
        entityB.destroy();

        expect(world.entities.length).toBe(1);
    });

    it('should encode world ID in entity', () => {
        const entity = world.spawn();
        const { worldId, entityId } = unpackEntity(entity);

        expect(worldId).toBe(world.id);
        expect(entityId).toBe(1);

        const world2 = createWorld();
        const entity2 = world2.spawn();
        const { worldId: worldId2, entityId: entityId2 } = unpackEntity(entity2);

        expect(worldId2).toBe(world2.id);
        expect(entityId2).toBe(1);
    });

    it('should recycle entities and increment generation', () => {
        const entities: Entity[] = [];

        for (let i = 0; i < 50; i++) {
            entities.push(world.spawn(Bar));
        }

        const bar = getStore(world, Bar);

        // Length should be 50 + 1 (world entity).
        expect(bar.value.length).toBe(51);

        for (const entity of entities) {
            entity.destroy();
        }

        // IDs are recycled in reverse order.
        let entity = world.spawn(Bar);
        let { generation, entityId } = unpackEntity(entity);
        expect(generation).toBe(1);
        expect(entityId).toBe(50);

        entity = world.spawn(Bar);
        ({ generation, entityId } = unpackEntity(entity));
        expect(generation).toBe(1);
        expect(entityId).toBe(49);

        entity = world.spawn(Bar);
        ({ generation, entityId } = unpackEntity(entity));
        expect(generation).toBe(1);
        expect(entityId).toBe(48);

        // Should remain the same and not increase because of the entity encoding.
        expect(bar.value.length).toBe(51);
    });

    it('should add entities with spawn', () => {
        const entity = world.spawn(Foo, Bar);

        expect(entity.has(Foo)).toBe(true);
        expect(entity.has(Bar)).toBe(true);
    });

    it('should return undefined for missing traits', () => {
        const entity = world.spawn();

        expect(entity.has(Bar)).toBe(false);
        expect(entity.get(Bar)).toEqual(undefined);
        expectTypeOf(entity.get(Bar)).toEqualTypeOf<{ value: number } | undefined>();

        expect(entity.has(Baz)).toBe(false);
        expect(entity.get(Baz)).toBeUndefined();
        expectTypeOf(entity.get(Baz)).toEqualTypeOf<{ value: number } | undefined>();
    });

    it('can add traits', () => {
        const entity = world.spawn();

        entity.add(Foo, Bar);

        expect(entity.has(Foo)).toBe(true);
        expect(entity.has(Bar)).toBe(true);
    });

    it('can add traits with initial state', () => {
        const entity = world.spawn(Bar({ value: 1 }));
        expect(entity.get(Bar)!.value).toBe(1);
    });

    it('can remove traits', () => {
        const entity = world.spawn(Foo, Bar);

        entity.remove(Foo);

        expect(entity.has(Foo)).toBe(false);
        expect(entity.has(Bar)).toBe(true);
    });

    it('can get trait state', () => {
        let entity = world.spawn(Bar({ value: 1 }));
        const bar = entity.get(Bar)!;
        expect(bar.value).toBe(1);

        // Changing trait state should not affect the entity.
        bar.value = 2;
        expect(entity.get(Bar)!.value).toBe(1);

        // Check this works with multi-generational entities.
        entity.destroy();

        entity = world.spawn(Bar({ value: 1 }));
        expect(entity.get(Bar)!.value).toBe(1);
    });

    it('can set trait state', () => {
        const entity = world.spawn(Bar);
        entity.set(Bar, { value: 1 });
        expect(entity.get(Bar)!.value).toBe(1);
    });

    it('can set trait state with a callback', () => {
        const entity = world.spawn(Bar);
        entity.set(Bar, (prev) => ({ value: prev.value + 1 }));
        expect(entity.get(Bar)!.value).toBe(1);
    });

    it('should trigger change events when trait state is set', () => {
        const entity = world.spawn(Bar);
        let called = false;

        world.onChange(Bar, () => {
            called = true;
        });

        entity.set(Bar, { value: 1 });
        expect(called).toBe(true);

        // Can optionally suppress the event.
        called = false;
        entity.set(Bar, { value: 2 }, false);
        expect(called).toBe(false);
    });

    it('can check if an entity is alive', () => {
        let entity = world.spawn();
        expect(entity.isAlive()).toBe(true);
        expect(entity.id()).toBe(1);
        expect(entity.generation()).toBe(0);

        entity.destroy();
        expect(entity.isAlive()).toBe(false);

        // Should be resilient to changes in generation with the same entity ID.
        entity = world.spawn(Bar);
        expect(entity.isAlive()).toBe(true);
        expect(entity.id()).toBe(1);
        expect(entity.generation()).toBe(1);

        entity.destroy();
        expect(entity.isAlive()).toBe(false);
    });

    it('can get entity id', () => {
        const entity = world.spawn();
        // The first entity is always 1 since a world entity is created first.
        expect(entity.id()).toBe(1);
    });

    it('can get entity generation', () => {
        const entity = world.spawn();
        expect(entity.generation()).toBe(0);

        entity.destroy();
        const entity2 = world.spawn();
        expect(entity2.generation()).toBe(1);
    });

    it('can check if entity exists in world', () => {
        const entity = world.spawn();
        expect(world.has(entity)).toBe(true);

        entity.destroy();
        expect(world.has(entity)).toBe(false);

        // Should work with world entities as well
        const worldEntity = world[$internal].worldEntity;
        expect(world.has(worldEntity)).toBe(true);
    });
});

/**
 * Storage type for trait data.
 * - AoS: Array of instances, one per entity
 * - SoA: Object with arrays, one array per property
 */
export type Store<T extends Schema = any> = T extends AoSFactory
    ? ReturnType<T>[]
    : {
          [P in keyof T]: T[P] extends (...args: never[]) => unknown ? ReturnType<T[P]>[] : T[P][];
      };

/**
 * Storage layout type.
 * - 'soa': Struct of Arrays - properties stored in separate arrays
 * - 'aos': Array of Structs - instances stored directly
 * - 'tag': No data storage - empty schema marker
 */
export type StoreType = 'aos' | 'soa' | 'tag';

/**
 * Schema definition for traits.
 * Can be a SoA object schema, an AoS factory function, or an empty object (tag).
 */
export type Schema =
    | {
          [key: string]: number | bigint | string | boolean | null | undefined | (() => unknown);
      }
    | AoSFactory
    | Record<string, never>;

/**
 * Factory function for AoS (Array of Structs) storage.
 * Returns a single instance that will be stored per entity.
 */
export type AoSFactory = () => unknown;

/**
 * Normalizes schema types to their primitive forms.
 * Ensures that explicit values like true, false or "string literal" are
 * normalized to their primitive types (boolean, string, etc).
 */
export type Norm<T extends Schema> =
    T extends Record<string, never>
        ? T
        : T extends AoSFactory
          ? () => ReturnType<T> extends number
                ? number
                : ReturnType<T> extends boolean
                  ? boolean
                  : ReturnType<T> extends string
                    ? string
                    : ReturnType<T>
          : {
                  [K in keyof T]: T[K] extends object
                      ? T[K] extends (...args: never[]) => unknown
                          ? T[K]
                          : never
                      : T[K] extends boolean
                        ? boolean
                        : T[K];
              }[keyof T] extends never
            ? never
            : {
                  [K in keyof T]: T[K] extends boolean ? boolean : T[K];
              };

import type { Schema } from './types';
import type { Store } from './types';

export function createStore<T extends Schema>(schema: T): Store<T>;
export function createStore(schema: Schema): unknown {
    if (typeof schema === 'function') {
        return [];
    } else {
        const store: Record<string, unknown[]> = {};

        for (const key in schema) {
            store[key] = [];
        }

        return store;
    }
}

import type { Schema } from './types';

function createSoASetFunction(schema: Schema) {
    const keys = Object.keys(schema);

    // Generate a hardcoded set function based on the schema keys
    const setFunctionBody = keys
        .map((key) => `if ('${key}' in value) store.${key}[index] = value.${key};`)
        .join('\n    ');

    // Use new Function to create a set function with hardcoded keys
    const set = new Function(
        'index',
        'store',
        'value',
        `
		${setFunctionBody}
	  `
    );

    return set;
}

function createSoAFastSetFunction(schema: Schema) {
    const keys = Object.keys(schema);

    // Generate a hardcoded set function based on the schema keys
    const setFunctionBody = keys.map((key) => `store.${key}[index] = value.${key};`).join('\n    ');

    // Use new Function to create a set function with hardcoded keys
    const set = new Function(
        'index',
        'store',
        'value',
        `
		${setFunctionBody}
	  `
    );

    return set;
}

// Return true if any trait value were changed.
function createSoAFastSetChangeFunction(schema: Schema) {
    const keys = Object.keys(schema);

    // Generate a hardcoded set function based on the schema keys
    const setFunctionBody = keys
        .map(
            (key) =>
                `if (store.${key}[index] !== value.${key}) {
            store.${key}[index] = value.${key};
            changed = true;
        }`
        )
        .join('\n    ');

    // Use new Function to create a set function with hardcoded keys
    const set = new Function(
        'index',
        'store',
        'value',
        `
        let changed = false;
        ${setFunctionBody}
        return changed;
        `
    );

    return set;
}

function createSoAGetFunction(schema: Schema) {
    const keys = Object.keys(schema);

    // Create an object literal with all keys assigned from the store
    const objectLiteral = `{ ${keys.map((key) => `${key}: store.${key}[index]`).join(', ')} }`;

    // Use new Function to create a get function that returns the pre-populated object
    const get = new Function(
        'index',
        'store',
        `
        return ${objectLiteral};
        `
    );

    return get;
}

function createAoSSetFunction(_schema: Schema) {
    return (index: number, store: any, value: any) => {
        store[index] = value;
    };
}

function createAoSFastSetChangeFunction(_schema: Schema) {
    return (index: number, store: any, value: any) => {
        let changed = false;
        if (value !== store[index]) {
            store[index] = value;
            changed = true;
        }
        return changed;
    };
}

function createAoSGetFunction(_schema: Schema) {
    return (index: number, store: any) => store[index];
}

const noop = () => {};
const createTagNoop = () => noop;

export const createSetFunction = {
    soa: createSoASetFunction,
    aos: createAoSSetFunction,
    tag: createTagNoop,
};

export const createFastSetFunction = {
    soa: createSoAFastSetFunction,
    aos: createAoSSetFunction,
    tag: createTagNoop,
};

export const createFastSetChangeFunction = {
    soa: createSoAFastSetChangeFunction,
    aos: createAoSFastSetChangeFunction,
    tag: createTagNoop,
};

export const createGetFunction = {
    soa: createSoAGetFunction,
    aos: createAoSGetFunction,
    tag: createTagNoop,
};

