import type { Entity } from '../entity/types';
import type { Trait } from '../trait/types';
import type { OrderedList } from './ordered-list';
import { $orderedTargetsTrait, $relation, $relationPair } from './symbols';

export type RelationTarget = Entity | '*';

/** A pair represents a relation + target combination */
export interface RelationPair<T extends Trait = Trait> {
    readonly [$relationPair]: true;
    [$internal]: {
        relation: Relation<T>;
        target: RelationTarget;
        params?: Record<string, unknown>;
    };
}

export type Relation<T extends Trait = Trait> = {
    readonly [$relation]: true;
    [$internal]: {
        trait: T;
        exclusive: boolean;
        autoDestroy: 'source' | 'target' | false;
    };
} & ((target: RelationTarget, params?: Record<string, unknown>) => RelationPair<T>);

export interface OrderedRelation<T extends Trait = Trait> extends Trait<() => OrderedList> {
    [$orderedTargetsTrait]: {
        relation: Relation<T>;
    };
}

import type { Entity } from '../types';
import {
    getEntityGeneration,
    getEntityId,
    getEntityWorldId,
    incrementGeneration,
    packEntity,
} from './pack-entity';

export type EntityIndex = {
    /** The number of currently alive entities. */
    aliveCount: number;
    /** Array of packed entities, densely packed. */
    dense: Entity[];
    /** Sparse array mapping entity IDs to their index in the dense array. */
    sparse: number[];
    /** The highest entity ID that has been assigned. */
    maxId: number;
    /** The current world ID. */
    worldId: number;
};

/**
 * Creates and initializes a new EntityIndex.
 * @param worldId - The ID of the world this index belongs to.
 * @returns A new EntityIndex object.
 */
export const createEntityIndex = (worldId: number): EntityIndex => ({
    aliveCount: 0,
    dense: [],
    sparse: [],
    maxId: 0,
    worldId,
});

/**
 * Adds a new entity ID to the index or recycles an existing one.
 * @param index - The EntityIndex to add to.
 * @returns The new or recycled packed entity.
 */
export const allocateEntity = (index: EntityIndex): Entity => {
    if (index.aliveCount < index.dense.length) {
        // Recycle entity
        const recycledEntity = incrementGeneration(index.dense[index.aliveCount]);
        index.dense[index.aliveCount] = recycledEntity;
        index.sparse[getEntityId(recycledEntity)] = index.aliveCount;
        index.aliveCount++;

        return recycledEntity;
    }
    // Create new entity
    const id = index.maxId++;
    const entity = packEntity(index.worldId, 0, id);
    index.dense.push(entity);
    index.sparse[id] = index.aliveCount;
    index.aliveCount++;

    return entity;
};

/**
 * Removes an entity ID from the index.
 * @param index - The EntityIndex to remove from.
 * @param entity - The packed entity to remove.
 */
export const releaseEntity = (index: EntityIndex, entity: Entity): void => {
    const id = getEntityId(entity);
    const denseIndex = index.sparse[id];
    if (denseIndex === undefined || denseIndex >= index.aliveCount) return;

    const lastIndex = index.aliveCount - 1;
    const lastEntity = index.dense[lastIndex];
    const lastId = getEntityId(lastEntity);

    // Swap with the last element
    index.sparse[lastId] = denseIndex;
    index.dense[denseIndex] = lastEntity;
    // Update the removed entity's record
    index.sparse[id] = lastIndex;
    index.dense[lastIndex] = entity;
    index.aliveCount--;
};

/**
 * Checks if an entity ID is currently alive in the index.
 * @param index - The EntityIndex to check.
 * @param entity - The packed entity to check.
 * @returns True if the entity is alive, false otherwise.
 */
export const isEntityAlive = /* @inline @pure */ (index: EntityIndex, entity: Entity): boolean => {
    const denseIndex = index.sparse[getEntityId(entity)];
    if (denseIndex === undefined || denseIndex >= index.aliveCount) return false;
    const storedEntity = index.dense[denseIndex];
    return (
        getEntityGeneration(entity) === getEntityGeneration(storedEntity) &&
        getEntityWorldId(entity) === index.worldId
    );
};

/**
 * Gets an array of all currently alive entities.
 * @param index - The EntityIndex to get alive entities from.
 * @returns An array of alive entities.
 */
export const getAliveEntities = (index: EntityIndex): Entity[] => {
    return index.dense.slice(0, index.aliveCount);
};

import type { Trait, TraitInstance } from './types';

export type TraitInstanceArray = (TraitInstance | undefined)[];

/**
 * Get TraitInstance by trait ID
 */
export /* @inline @pure */ function getTraitInstance(
    traitData: TraitInstanceArray,
    trait: Trait
): TraitInstance | undefined {
    return traitData[trait.id];
}

/**
 * Set TraitInstance by trait ID
 */
export /* @inline */ function setTraitInstance(
    traitData: TraitInstanceArray,
    trait: Trait,
    data: TraitInstance
): void {
    const traitId = trait.id;
    // Ensure array is large enough
    if (traitId >= traitData.length) {
        traitData.length = traitId + 1;
    }
    traitData[traitId] = data;
}

/**
 * Check if trait is registered
 */
export /* @inline @pure */ function hasTraitInstance(
    traitData: TraitInstanceArray,
    trait: Trait
): boolean {
    const traitId = trait.id;
    return traitId < traitData.length && traitData[traitId] !== undefined;
}

/**
 * Clear all trait data
 */
export /* @inline */ function clearTraitInstance(traitData: TraitInstanceArray): void {
    traitData.length = 0;
}

/**
 * Storage type for trait data.
 * - AoS: Array of instances, one per entity
 * - SoA: Object with arrays, one array per property
 */
export type Store<T extends Schema = any> = T extends AoSFactory
    ? ReturnType<T>[]
    : {
          [P in keyof T]: T[P] extends (...args: never[]) => unknown ? ReturnType<T[P]>[] : T[P][];
      };

/**
 * Storage layout type.
 * - 'soa': Struct of Arrays - properties stored in separate arrays
 * - 'aos': Array of Structs - instances stored directly
 * - 'tag': No data storage - empty schema marker
 */
export type StoreType = 'aos' | 'soa' | 'tag';

/**
 * Schema definition for traits.
 * Can be a SoA object schema, an AoS factory function, or an empty object (tag).
 */
export type Schema =
    | {
          [key: string]: number | bigint | string | boolean | null | undefined | (() => unknown);
      }
    | AoSFactory
    | Record<string, never>;

/**
 * Factory function for AoS (Array of Structs) storage.
 * Returns a single instance that will be stored per entity.
 */
export type AoSFactory = () => unknown;

/**
 * Normalizes schema types to their primitive forms.
 * Ensures that explicit values like true, false or "string literal" are
 * normalized to their primitive types (boolean, string, etc).
 */
export type Norm<T extends Schema> =
    T extends Record<string, never>
        ? T
        : T extends AoSFactory
          ? () => ReturnType<T> extends number
                ? number
                : ReturnType<T> extends boolean
                  ? boolean
                  : ReturnType<T> extends string
                    ? string
                    : ReturnType<T>
          : {
                  [K in keyof T]: T[K] extends object
                      ? T[K] extends (...args: never[]) => unknown
                          ? T[K]
                          : never
                      : T[K] extends boolean
                        ? boolean
                        : T[K];
              }[keyof T] extends never
            ? never
            : {
                  [K in keyof T]: T[K] extends boolean ? boolean : T[K];
              };

import type { Schema, StoreType } from './types';

/**
 * Get default values from a schema.
 * Returns null for tags (empty schemas) or if no defaults exist.
 */
/* @inline @pure */ export function getSchemaDefaults(
    schema: Record<string, any> | (() => unknown),
    type: StoreType
): Record<string, any> | null {
    if (type === 'aos') {
        return typeof schema === 'function' ? (schema() as Record<string, any>) : null;
    }

    if (!schema || typeof schema === 'function' || Object.keys(schema).length === 0) return null;

    const defaults: Record<string, any> = {};
    for (const key in schema) {
        if (typeof schema[key] === 'function') {
            defaults[key] = schema[key]();
        } else {
            defaults[key] = schema[key];
        }
    }
    return defaults;
}

export /* @inline @pure */ function validateSchema(schema: Schema) {
    for (const key in schema) {
        const value = schema[key as keyof Schema];
        if (value !== null && typeof value === 'object') {
            const kind = Array.isArray(value) ? 'array' : 'object';
            throw new Error(`Koota: ${key} is an ${kind}, which is not supported in traits.`);
        }
    }
}

