/**
 * Error thrown when map conflicts are detected and mapConflictPolicy is 'error'.
 */
export class MapConflictError extends Error {
  /**
   * @param {string} message
   * @param {Array<MapConflict>} conflicts
   */
  constructor (message, conflicts) {
    super(message)
    this.name = 'MapConflictError'
    /**
     * The conflicts that caused this error.
     * @type {Array<MapConflict>}
     */
    this.conflicts = conflicts
  }
}

/**
 * Create a summary from an array of conflicts.
 *
 * @param {Array<MapConflict>} conflicts
 * @return {MapConflictSummary}
 */
export const createMapConflictSummary = conflicts => {
  const byType = {}
  const byKey = {}
  const byParent = {}
  const bySource = {}
  for (const conflict of conflicts) {
    byType[conflict.type] = (byType[conflict.type] || 0) + 1
    byKey[conflict.key] = (byKey[conflict.key] || 0) + 1
    byParent[conflict.parentId] = (byParent[conflict.parentId] || 0) + 1
    bySource[conflict.source] = (bySource[conflict.source] || 0) + 1
  }
  return {
    count: conflicts.length,
    total: conflicts.length,
    byType,
    byKey,
    byParent,
    bySource
  }
}

/**
 * Determine if a value is a Yjs Type or contains subdocs.
 *
 * @param {*} value
 * @return {boolean}
 */
const isYjsValue = value => {
  if (value == null) return false
  // We can't directly import YType/Doc here due to circular deps, so use duck typing
  return typeof value === 'object' && (
    value.constructor != null &&
    (value.constructor.name === 'YType' || value.constructor.name === 'Doc')
  )
}

/**
 * Build a write snapshot summary.
 *
 * @param {string} key
 * @param {*} value
 * @param {'set'|'delete'} op
 * @return {MapConflictWrite}
 */
const buildWrite = (key, value, op) => {
  let summary
  if (op === 'delete') {
    summary = `delete key '${key}'`
  } else {
    const valStr = value != null && typeof value === 'object'
      ? value.constructor.name
      : JSON.stringify(value)
    summary = `set key '${key}' to value ${valStr}`
  }
  return {
    snapshot: {
      summary
    }
  }
}

/**
 * Build a conflict object.
 *
 * @param {string} key
 * @param {string} parentId
 * @param {Array<{value: *, op: 'set'|'delete', local: boolean}>} writes
 * @return {MapConflict}
 */
export const buildConflict = (key, parentId, writes) => {
  // Determine type
  const hasSet = writes.some(w => w.op === 'set')
  const hasDelete = writes.some(w => w.op === 'delete')
  /** @type {MapConflictType} */
  let type
  if (hasSet && hasDelete) {
    type = 'delete-set'
  } else {
    type = 'set-set'
  }

  // Determine source
  const hasLocal = writes.some(w => w.local)
  const hasRemote = writes.some(w => !w.local)
  /** @type {MapConflictSource} */
  let source
  if (hasLocal && hasRemote) {
    source = 'mixed'
  } else if (hasLocal) {
    source = 'local'
  } else {
    source = 'remote'
  }

  // Check for ambiguity - Yjs types or subdocs make it ambiguous
  const hasYjsValue = writes.some(w => w.op === 'set' && isYjsValue(w.value))
  const ambiguous = hasYjsValue
  const conflictType = ambiguous ? 'ambiguous' : 'deterministic'

  // Determine winner (last write wins by client id for tiebreaking)
  const lastWrite = writes[writes.length - 1]
  const winner = lastWrite.op === 'set' ? lastWrite.value : undefined

  const message = `Map conflict on key '${key}' in parent '${parentId}': ${type} conflict (${source})`

  return {
    key,
    parentId,
    type,
    source,
    message,
    writes: writes.map(w => buildWrite(key, w.value, w.op)),
    resolution: {
      winner,
      strategy: 'lastWriteWins',
      deterministic: !ambiguous
    },
    ambiguous,
    conflictType
  }
}

